import pandas as pd
import numpy as np
import json

DATA_FILE = "/home/chs/Work/tga_plot/tests/inputs/blank_rows_on_top.xlsx"

# Read the Excel file with header at row 8 (0-indexed: row 7)
df = pd.read_excel(DATA_FILE, sheet_name="Sheet1", header=7)

# Extract columns: C=Temperature, D=Weight(%), E=D.W(%/C)
temp = df["Temperature"].values
weight = df["Weight(%)"].values
dw = df["D.W(%/C)"].values

# Prepare data for ECharts
data_weight = [[float(t), float(w)] for t, w in zip(temp, weight)]
data_dw = [[float(t), float(d)] for t, d in zip(temp, dw)]

option = {
    "title": {
        "text": "TGA 분석 결과",
        "left": "center",
        "textStyle": {"fontFamily": "Noto Sans CJK KR"}
    },
    "tooltip": {
        "trigger": "axis",
        "axisPointer": {"type": "cross"},
        "textStyle": {"fontFamily": "Noto Sans CJK KR"}
    },
    "legend": {
        "data": ["Weight(%)", "D.W(%/C)"],
        "top": 30,
        "textStyle": {"fontFamily": "Noto Sans CJK KR"}
    },
    "grid": {
        "left": "8%",
        "right": "8%",
        "bottom": "12%",
        "containLabel": True
    },
    "xAxis": {
        "name": "Temperature (°C)",
        "type": "value",
        "nameTextStyle": {"fontFamily": "Noto Sans CJK KR"},
        "axisLabel": {"formatter": "{value}"}
    },
    "yAxis": [
        {
            "name": "Weight (%)",
            "type": "value",
            "position": "left",
            "nameTextStyle": {"fontFamily": "Noto Sans CJK KR"},
            "axisLabel": {"formatter": "{value}"}
        },
        {
            "name": "D.W (%/C)",
            "type": "value",
            "position": "right",
            "nameTextStyle": {"fontFamily": "Noto Sans CJK KR"},
